DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'jewelry_material_type_check_v2') THEN ALTER TABLE public.jewelry ADD CONSTRAINT jewelry_material_type_check_v2 CHECK (material_type IN ('gold_14k', 'gold_18k', 'gold_21k', 'gold_22k', 'gold_24k', 'silver', 'diamond')); ALTER TABLE public.jewelry DROP CONSTRAINT IF EXISTS jewelry_material_type_check; ALTER TABLE public.jewelry RENAME CONSTRAINT jewelry_material_type_check_v2 TO jewelry_material_type_check; END IF; END $$;